دالة اجمع_المتداخل(خ) {
    متغير م = ٠
    من_أجل (مفتاح في مفاتيح(خ)) {
        متغير قيمة = خ[مفتاح]
        إذا (نوع(قيمة) == "رقم") {
            م = م + قيمة
        } وإلا إذا (نوع(قيمة) == "خريطة") {
            م = م + اجمع_المتداخل(قيمة)
        }
    }
    ارجع م
}
```

